import assert from 'node:assert/strict';
import { app, BrowserWindow } from 'electron';
import { writeFileSync } from 'node:fs';
const url = process.argv.find((value) => value.startsWith('http://'));
if (!url || !process.env.LINGXI_TEST_USER_DATA) throw new Error('isolated fixture required');
app.setPath('userData', process.env.LINGXI_TEST_USER_DATA);
const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
async function main() {
  await app.whenReady();
  const win = new BrowserWindow({ show: false, width: 1040, height: 1080, webPreferences: { sandbox: true, backgroundThrottling: false } });
  const run = (code) => win.webContents.executeJavaScript(code);
  const wait = async (expression) => { for (let i = 0; i < 150; i++) { if (await run(expression)) return; await delay(20); } throw new Error(`Timed out: ${expression}`); };
  const click = (selector) => run(`document.querySelector(${JSON.stringify(selector)}).click()`);
  const select = async (label, value) => { await run(`(() => { const el=Array.from(document.querySelectorAll('select')).find(el=>el.getAttribute('aria-label')===${JSON.stringify(label)});el.value=${JSON.stringify(value)};el.dispatchEvent(new Event('change',{bubbles:true})); })()`); await wait(`!document.querySelector('[role=status]')`); };
  const input = async (selector, value) => { await run(`(() => { const el=document.querySelector(${JSON.stringify(selector)});Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(el,${JSON.stringify(value)});el.dispatchEvent(new Event('input',{bubbles:true})); })()`); await delay(30); };
  const screenshot = async (name) => { await run(`document.querySelector('.settings-content-scroll').scrollTop=0`); await delay(60); if (process.env.LINGXI_COMPUTER_SETTINGS_SCREENSHOT_DIR) writeFileSync(`${process.env.LINGXI_COMPUTER_SETTINGS_SCREENSHOT_DIR}/${name}.png`, (await win.webContents.capturePage()).toPNG()); };
  try {
    await win.loadURL(url);
    await wait(`document.querySelector('[aria-label="Allow computer use"]')?.disabled === false`);
    win.webContents.debugger.attach('1.3');
    await win.webContents.debugger.sendCommand('Emulation.setFocusEmulationEnabled', { enabled: true });
    console.error('computer-settings-checkpoint: loaded');
    await run('window.computerSettingsFixture.hold()');
    await click('[aria-label="Allow computer use"]');
    assert.equal(await run(`document.querySelector('[aria-label="Allow computer use"]').getAttribute('aria-checked')`), 'true', 'save is not optimistically shown');
    assert.equal(await run(`document.querySelector('[aria-label="Allow computer use"]').disabled`), true, 'mutations are serialized');
    await run('window.computerSettingsFixture.release()');
    await wait(`document.querySelector('[aria-label="Allow computer use"]').getAttribute('aria-checked') === 'false' && !document.querySelector('[role=status]')`);
    assert.equal(await run('window.computerSettingsFixture.commands[0].revision'), 'r0');
    await run(`window.computerSettingsFixture.fail('Settings changed; reload.');`);
    await click('[aria-label="Allow computer use"]');
    await wait(`document.querySelector('[role=alert]')?.textContent.includes('Settings changed')`);
    assert.equal(await run(`document.querySelector('[aria-label="Allow computer use"]').getAttribute('aria-checked')`), 'false');
    await run('window.computerSettingsFixture.external(true)');
    await wait(`document.querySelector('[aria-label="Allow computer use"]').getAttribute('aria-checked') === 'true'`);
    await click('.computer-settings-error button');
    await wait(`!document.querySelector('[role=alert]')`);
    console.error('computer-settings-checkpoint: master-tested');
    await click('[aria-label="Revoke permanent access to Finder"]');
    await wait(`!document.querySelector('[aria-label="Revoke permanent access to Finder"]') && document.querySelector('[aria-label="App permission for Finder"]')?.value === 'deny'`);
    await select('App permission for Finder', 'ask');
    assert.equal(await run(`window.computerSettingsFixture.commands.at(-1).permission`), 'ask');
    await input('#computer-app-bundle-id', 'com.example.installed');
    await run(`document.querySelector('.computer-settings-add-form').requestSubmit()`);
    await wait(`Boolean(document.querySelector('[aria-label="Revoke permanent access to Installed app"]'))`);
    console.error('computer-settings-checkpoint: app-tested');
    await screenshot('computer-settings-light');
    await run('window.computerSettingsFixture.setDark(true)'); await delay(40); await screenshot('computer-settings-dark');
    console.error('computer-settings-checkpoint: browser-open');
    await click('[aria-label="Manage Google Chrome"]');
    await wait(`document.activeElement?.textContent === 'Google Chrome'`);
    await select('History access', 'allow');
    await select('Default browsing permission', 'deny');
    assert.equal(await run(`window.computerSettingsFixture.commands.at(-1).key`), 'defaultBrowsing');
    await click('.computer-browser-add');
    await wait(`document.activeElement?.id === 'computer-browser-site-origin'`);
    await input('#computer-browser-site-origin', 'https://docs.example.com');
    await run(`document.querySelector('#computer-browser-add-site').requestSubmit()`);
    await wait(`Boolean(document.querySelector('[aria-label="Browsing permission for https://docs.example.com"]'))`);
    await wait(`document.activeElement?.classList.contains('computer-browser-add') === true`);
    console.error('computer-settings-checkpoint: site-added');
    await select('Download permission for https://docs.example.com', 'allow');
    await click('[aria-label="Enable full CDP access"]');
    await wait(`document.querySelector('[aria-label="Enable full CDP access"]').getAttribute('aria-checked') === 'true' && !document.querySelector('[role=status]')`);
    await click('[aria-label="Use site tools by default"]');
    await wait(`document.querySelector('[aria-label="Use site tools by default"]').getAttribute('aria-checked') === 'false' && !document.querySelector('[role=status]')`);
    console.error('computer-settings-checkpoint: browser-permissions-tested');
    await screenshot('browser-settings-dark');
    await run('window.computerSettingsFixture.setDark(false)'); await delay(40); await screenshot('browser-settings-light');
    await click('[aria-label="Remove permissions for https://docs.example.com"]');
    await wait(`!document.querySelector('[aria-label="Browsing permission for https://docs.example.com"]') && !document.querySelector('[role=status]')`);
    await run(`Array.from(document.querySelectorAll('.computer-browser-toolbar button')).find(el => el.textContent === 'Set up extension').click()`);
    await wait(`document.querySelector('.computer-browser-remove')?.disabled === false && !document.querySelector('[role=status]')`);
    await run(`Array.from(document.querySelectorAll('.computer-browser-toolbar button')).find(el => el.textContent === 'Retry').click()`);
    await wait(`document.querySelector('.computer-browser-heading p')?.textContent === 'Browser extension connected' && !document.querySelector('[role=status]')`);
    console.error('computer-settings-checkpoint: connection-tested');
    await click('.computer-browser-breadcrumb button');
    await wait(`document.activeElement?.getAttribute('aria-label') === 'Manage Google Chrome'`);
    console.error('computer-settings-checkpoint: returned');
    await run('window.computerSettingsFixture.unavailable()');
    console.error('computer-settings-checkpoint: unavailable-published');
    await wait(`document.querySelector('[role=alert]')?.textContent.includes('Device settings are unreadable')`);
    assert.equal(await run(`document.querySelector('[aria-label="Allow computer use"]').disabled`), true);
    assert.equal(await run(`document.querySelector('[aria-label="App permission for Finder"]').disabled`), true);
    console.error('computer-settings-checkpoint: all-assertions-passed');
    console.log(JSON.stringify({ passed: true, commandCount: await run('window.computerSettingsFixture.commands.length') }));
  } finally { console.error('computer-settings-checkpoint: destroying'); win.destroy(); console.error('computer-settings-checkpoint: destroyed'); }
}
main().then(() => app.exit(0)).catch((error) => { console.error(error); app.exit(1); });
